-- Reconocimiento histórico al ejecutar esta migración, sin avisos retroactivos.
BEGIN;
-- Evita competir con concesiones o borrados durante la inicialización.
LOCK TABLE challenge_rewards, user_achievements, erased_users IN SHARE ROW EXCLUSIVE MODE;
ALTER TABLE achievements DROP CONSTRAINT IF EXISTS achievements_metric_check;
ALTER TABLE achievements ADD CONSTRAINT achievements_metric_check CHECK (metric IN ('TRANSLATIONS_COMPLETED','SIGNS_LEARNED','ALPHABET_COMPLETED','SESSIONS_COMPLETED','CATALOG_REQUIREMENT','ACTIVE_SECONDS','VOICE_COMPLETED','FAVORITE_WORD','DISTINCT_WORDS','LETTERS_VIEWED','BOTH_MODES','TRANSLATION_DAYS','WORD_CATEGORIES','DAILY_CHALLENGE_POINTS'));
ALTER TABLE achievements DROP CONSTRAINT IF EXISTS ck_achievement_available_measurement;
ALTER TABLE achievements ADD CONSTRAINT ck_achievement_available_measurement CHECK (availability <> 'available' OR metric IN ('TRANSLATIONS_COMPLETED','ACTIVE_SECONDS','VOICE_COMPLETED','FAVORITE_WORD','DISTINCT_WORDS','LETTERS_VIEWED','BOTH_MODES','TRANSLATION_DAYS','WORD_CATEGORIES','DAILY_CHALLENGE_POINTS'));
INSERT INTO achievements(code,name,description,metric,target_count,points,icon_reference,collection,availability,category,level,localizations,is_active) VALUES ('dailyChallengePoints500','500 puntos de retos diarios','Gana 500 puntos en recompensas de retos diarios. Esta medalla no concede puntos adicionales.','DAILY_CHALLENGE_POINTS',500,0,'ribbon','catalog','available','consistency','bronze','{"es": {"name": "500 puntos de retos diarios", "description": "Gana 500 puntos en recompensas de retos diarios. Esta medalla no concede puntos adicionales."}, "en": {"name": "500 daily challenge points", "description": "Earn 500 points from daily challenge rewards. This medal grants no additional points."}, "fr": {"name": "500 points de défis quotidiens", "description": "Gagnez 500 points grâce aux récompenses des défis quotidiens. Cette médaille ne rapporte aucun point supplémentaire."}, "pt": {"name": "500 pontos de desafios diários", "description": "Ganhe 500 pontos em recompensas de desafios diários. Esta medalha não concede pontos adicionais."}}'::jsonb,TRUE) ON CONFLICT(code) DO NOTHING;
INSERT INTO achievements(code,name,description,metric,target_count,points,icon_reference,collection,availability,category,level,localizations,is_active) VALUES ('dailyChallengePoints1000','1.000 puntos de retos diarios','Gana 1.000 puntos en recompensas de retos diarios. Esta medalla no concede puntos adicionales.','DAILY_CHALLENGE_POINTS',1000,0,'ribbon','catalog','available','consistency','silver','{"es": {"name": "1.000 puntos de retos diarios", "description": "Gana 1.000 puntos en recompensas de retos diarios. Esta medalla no concede puntos adicionales."}, "en": {"name": "1,000 daily challenge points", "description": "Earn 1,000 points from daily challenge rewards. This medal grants no additional points."}, "fr": {"name": "1 000 points de défis quotidiens", "description": "Gagnez 1 000 points grâce aux récompenses des défis quotidiens. Cette médaille ne rapporte aucun point supplémentaire."}, "pt": {"name": "1.000 pontos de desafios diários", "description": "Ganhe 1.000 pontos em recompensas de desafios diários. Esta medalha não concede pontos adicionais."}}'::jsonb,TRUE) ON CONFLICT(code) DO NOTHING;
INSERT INTO achievements(code,name,description,metric,target_count,points,icon_reference,collection,availability,category,level,localizations,is_active) VALUES ('dailyChallengePoints3000','3.000 puntos de retos diarios','Gana 3.000 puntos en recompensas de retos diarios. Esta medalla no concede puntos adicionales.','DAILY_CHALLENGE_POINTS',3000,0,'ribbon','catalog','available','consistency','gold','{"es": {"name": "3.000 puntos de retos diarios", "description": "Gana 3.000 puntos en recompensas de retos diarios. Esta medalla no concede puntos adicionales."}, "en": {"name": "3,000 daily challenge points", "description": "Earn 3,000 points from daily challenge rewards. This medal grants no additional points."}, "fr": {"name": "3 000 points de défis quotidiens", "description": "Gagnez 3 000 points grâce aux récompenses des défis quotidiens. Cette médaille ne rapporte aucun point supplémentaire."}, "pt": {"name": "3.000 pontos de desafios diários", "description": "Ganhe 3.000 pontos em recompensas de desafios diários. Esta medalha não concede pontos adicionais."}}'::jsonb,TRUE) ON CONFLICT(code) DO NOTHING;
-- Solo usuarios con recompensas reales; los demás leen cero sin crear filas.
INSERT INTO user_achievements(user_id,achievement_id,current_count,achieved_at)
SELECT r.user_id,a.achievement_id,r.total,
       CASE WHEN r.total >= a.target_count THEN CURRENT_TIMESTAMP ELSE NULL END
FROM (SELECT user_id,sum(points)::integer AS total FROM challenge_rewards GROUP BY user_id) r
CROSS JOIN achievements a
WHERE a.code IN ('dailyChallengePoints500','dailyChallengePoints1000','dailyChallengePoints3000')
  AND NOT EXISTS (SELECT 1 FROM erased_users e WHERE e.user_id=r.user_id)
ON CONFLICT(user_id,achievement_id) DO NOTHING;
COMMIT;
